#include <bits/stdc++.h>
using namespace std;

using ll = long long;

ll calculate(ll a, ll b, char op) {
    return op == '*' ? a * b : a + b;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    vector<ll> n(4);
    char q, w, e;

    cin >> n[0] >> n[1] >> n[2] >> n[3] >> q >> w >> e;

    sort(n.begin(), n.end());
    ll mn = LLONG_MAX;

    do {
        ll a = n[0], b = n[1], c = n[2], d = n[3];

        mn = min(mn, calculate(calculate(a, b, q), calculate(c, d, w), e));
        mn = min(mn, calculate(calculate(a, c, q), calculate(b, d, w), e));
        mn = min(mn, calculate(calculate(a, d, q), calculate(b, c, w), e));
        mn = min(mn, calculate(calculate(calculate(a, b, q), c, w), d, e));
    } while (next_permutation(n.begin(), n.end()));

    cout << mn;
    return 0;
}

